-- INSERT atomicity (a malformed row after the first 1000 rows writes
-- nothing of the block, also through a materialized view) and FixedString
-- comparison across lengths (zero padding).

CREATE TABLE pe (k String, v UInt32) ENGINE = MergeTree ORDER BY k;

CREATE TABLE pr (k String, s UInt64, n UInt64) ENGINE = SummingMergeTree ORDER BY k;

CREATE MATERIALIZED VIEW pmv TO pr AS SELECT k, sum(v) AS s, count() AS n FROM pe GROUP BY k;

