-- query: resend counted once
SELECT k, sum(s), sum(n) FROM pr GROUP BY k ORDER BY k;

-- query: fixedstring mixed lengths
SELECT toFixedString('ab',4) = toFixedString('ab',2), toFixedString('ab',4) > toFixedString('ab',2), toFixedString('ab',4) < toFixedString('ab',2), toFixedString('ab',4) IN (toFixedString('ab',2)), toFixedString('abc',4) > toFixedString('ab',2), toFixedString('ab',2) = toFixedString('ab\0\0\0', 5), toFixedString('ab',2) < toFixedString('ab\0\0c', 5);

CREATE TABLE fs (id UInt8, f FixedString(4), g FixedString(4)) ENGINE = MergeTree ORDER BY (f, id);

INSERT INTO fs VALUES (1, 'ab', 'ab'), (2, 'abc', 'abc');

-- query: fixedstring key equality with shorter literal
SELECT id FROM fs WHERE f = toFixedString('ab', 2) ORDER BY id;

-- query: fixedstring non-key equality with shorter literal
SELECT id FROM fs WHERE g = toFixedString('ab', 2) ORDER BY id;

-- query: fixedstring key IN with other lengths
SELECT id FROM fs WHERE f IN (toFixedString('ab', 2), toFixedString('abc', 3)) ORDER BY id;

-- query: fixedstring non-key IN with other lengths
SELECT id FROM fs WHERE g IN (toFixedString('ab', 2), toFixedString('abc', 3)) ORDER BY id;

-- query: fixedstring key range with shorter literal
SELECT id FROM fs WHERE f > toFixedString('ab', 2) ORDER BY id;

-- query: fixedstring non-key range with shorter literal
SELECT id FROM fs WHERE g <= toFixedString('ab', 2) ORDER BY id;

-- query: fixedstring non-key equality with longer literal
SELECT id FROM fs WHERE g = toFixedString('abc', 8) ORDER BY id;
